// Agent workspace (desktop-first): triage, providers, quotes, approvals, bookings, tasks, messages, complaints, performance.
import { ApiError, ago, api, cap, dateOnly, dt, dtl, esc, go, html, hoursText, icon, inDays, inr, istInput, meta, openFile, phone, qs, raw, statusInfo, upload } from '../core.js';
import { avatar, barChart, chat, chip, composer, confirmDialog, emptyState, field, hbars, kv, modal, mountTable, note, opts, pageHeader, progress, requestTimeline, rowBtn, section, stars, stat, statusChip, tabs, timeline, toast, verified } from '../ui.js';

const S = (...p) => p.map(String).join('');
const catIc = (c, size = 40) => html`<span class="cat-ic" style="background:${c.color || c.category_color || '#E6F4D7'};width:${size}px;height:${size}px;font-size:${Math.round(size * 0.5)}px" aria-hidden="true">${c.icon || c.category_icon || '✨'}</span>`;
const QS = { submitted: ['To validate', 'warn'], shared: ['Shared', 'info'], approved: ['Approved', 'success'], rejected: ['Declined', 'danger'], clarification_requested: ['Question', 'warn'], revised_pending_consent: ['Re-approval', 'warn'], not_selected: ['Not selected', 'neutral'], withdrawn: ['Withdrawn', 'neutral'], expired: ['Expired', 'neutral'] };
const qChip = (s) => chip(...(QS[s] || [cap(s), 'neutral']));
const BS = { confirmed: 'info', on_the_way: 'info', in_progress: 'warn', work_done: 'warn', completed: 'success', cancelled: 'neutral', pending_reconsent: 'warn', disputed: 'danger' };
const bChip = (s) => chip(cap(s), BS[s] || 'neutral');
async function act(el, fn) { const l = el.innerHTML; el.disabled = true; el.innerHTML = '<span class="spin"></span>'; try { return await fn(); } catch (e) { toast(e.message || 'Something went wrong', 'error'); } finally { if (el.isConnected) { el.disabled = false; el.innerHTML = l; } } }
const lead = (u) => u.roles.includes('team_lead');
const ageChip = (r) => (r.overdue ? chip('SLA overdue', 'danger') : r.age_hours > 24 ? chip(hoursText(r.age_hours), 'warn') : chip(hoursText(r.age_hours), 'neutral'));

// ---------------------------------------------------------------- home
async function home(ctx) {
  const d = await api('/agent/dashboard');
  const w = d.workload; const pct = Math.round((w.active_requests * 100) / w.capacity_limit);
  const c = d.counts;
  return html`${pageHeader(`Good ${new Date().getHours() < 12 ? 'morning' : 'afternoon'}, ${d.agent.name}`, 'Here are the requests that need your attention today.', html`<a class="btn btn-primary" href="#/a/requests">${icon('inbox', 18)} Request inbox</a>`)}
    <div class="grid g4">${stat({ label: 'Open requests', value: c.open, ic: 'inbox', href: '#/a/requests' })}${stat({ label: 'Follow-ups due', value: c.followups_due, ic: 'clock', tone: c.followups_due ? 'warn' : '', href: '#/a/tasks' })}${stat({ label: 'Awaiting approval', value: c.awaiting_approval, ic: 'check', tone: 'info', href: '#/a/approvals' })}${stat({ label: 'Quotes to validate', value: c.quotes_to_validate, ic: 'file', tone: c.quotes_to_validate ? 'warn' : '', href: '#/a/quotes' })}</div>
    <div class="split mt"><div>${d.next_best_action ? html`<div class="nba"><b>Next best action</b><div class="row between wrap"><span>${d.next_best_action.text}</span><a class="btn btn-primary btn-sm" href="#/a/request/${d.next_best_action.request_id}">Open request</a></div></div>` : ''}
      ${section('Priority queue', d.queue.length ? html`<div>${d.queue.map((q) => html`<a class="queue-item" href="#/a/request/${q.id}">${catIc(q)}<div class="grow"><b>${q.reference}</b> · ${q.title} ${q.priority === 'urgent' ? chip('Urgent', 'danger') : ''}<div class="muted sm">${q.customer_name} · ${q.next_action} · ${q.status_label}</div></div>${chip(q.tag, { 'Due now': 'danger', 'Follow up': 'warn', Ready: 'success', Monitor: 'neutral' }[q.tag])}${icon('right', 18, 'chev')}</a>`)}</div>` : emptyState({ ic: 'check', title: 'All clear', text: 'No open requests assigned to you. Check the pool for unassigned work.', action: html`<a class="btn btn-secondary" href="#/a/requests?scope=pool">Open pool (${c.pool})</a>` }))}</div>
    <div>${section('Workload', html`<div class="card"><div class="row between"><b>${w.active_requests} of ${w.capacity_limit}</b>${chip(cap(w.availability_status), w.availability_status === 'available' ? 'success' : 'warn')}</div><div class="gauge mt ${pct > 90 ? 'hot' : pct > 70 ? 'warm' : ''}"><i style="width:${Math.min(100, pct)}%"></i></div><p class="muted xs" style="margin:8px 0 0">Capacity is configured by admin; completed this week: ${c.completed_week}.</p></div>`)}
      ${section('Follow-ups & tasks', html`<div class="card" style="padding:4px 16px">${d.tasks.length ? d.tasks.map((t) => html`<div class="list-item"><div class="grow"><b>${t.title}</b><div class="muted sm">${t.reference ? t.reference + ' · ' : ''}${t.due_at ? (t.overdue ? 'Overdue ' : 'Due ') + ago(t.due_at) : 'No due date'}</div></div>${t.overdue ? chip('Overdue', 'danger') : ''}</div>`) : '<p class="muted" style="padding:12px 0">No open tasks.</p>'}</div>`, html`<a href="#/a/tasks">All tasks</a>`)}
      ${c.pool ? html`<a class="card card-link card-soft mt" href="#/a/requests?scope=pool"><b>${c.pool} unassigned request${c.pool > 1 ? 's' : ''} in the pool</b><div class="muted sm">Claim work when you have capacity.</div></a>` : ''}</div></div>`;
}

// ---------------------------------------------------------------- customers
async function customers(ctx) {
  ctx.after(() => mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/agent/customers' + qs({ ...p, agent_id: ctx.query.agent_id })), search: 'Search by name or mobile', rowHref: (c) => '#/a/customer/' + c.id,
    onLoaded: (r) => { const el = ctx.view.querySelector('#cap'); if (el && r.capacity) el.textContent = `${r.total_customers} dedicated customers · ${r.capacity.active_requests}/${r.capacity.capacity_limit} active requests`; },
    columns: [{ label: 'Customer', render: (c) => html`<div class="row">${avatar(c.name, c.avatar_color, 34)}<div><b>${c.name}</b><span class="sub">${phone(c.mobile)}</span></div></div>` }, { label: 'My role', render: (c) => chip(cap(c.my_role), c.my_role === 'primary' ? 'lime' : 'neutral') }, { label: 'Plan', render: (c) => c.plan || 'Basic' },
      { label: 'Open', cls: 'num', render: (c) => c.open_requests }, { label: 'Total', cls: 'num', render: (c) => c.total_requests }, { label: 'Last request', render: (c) => (c.last_request_at ? ago(c.last_request_at) : '—') }],
    empty: { ic: 'users', title: 'No customers assigned yet', text: 'New customers are allocated to you automatically.' },
  }));
  return html`${pageHeader('My customer portfolio', html`<span id="cap">Maintain continuity across your assigned customers.</span>`)}<div id="tbl"></div>`;
}

async function customerProfile(ctx) {
  const c = await api('/agent/customers/' + ctx.params.id);
  return html`<a href="#/a/customers" class="muted sm">← My customers</a>${pageHeader(c.name, `Customer since ${dateOnly(c.created_at)}`, html`${c.conversation_id ? html`<a class="btn btn-secondary" href="#/a/messages?c=${c.conversation_id}">${icon('chat', 18)} Message</a>` : ''}<a class="btn btn-primary" href="tel:${c.mobile}">${icon('phone', 18)} Call ${phone(c.mobile)}</a>`)}
    ${note('You see only the information needed to coordinate requests. Street addresses are visible on the request itself.', 'info')}
    <div class="grid g4 mt">${stat({ label: 'Requests', value: c.stats.total })}${stat({ label: 'Completed', value: c.stats.completed, ic: 'check' })}${stat({ label: 'Complaints', value: c.stats.complaints, ic: 'alert', tone: c.stats.complaints ? 'warn' : '' })}${stat({ label: 'Plan', value: c.membership ? c.membership.plan : 'Basic' })}</div>
    <div class="split mt"><div>${section('Requests', c.requests.length ? html`<div class="card" style="padding:4px 16px">${c.requests.map((r) => html`<a class="list-item" href="#/a/request/${r.id}">${catIc(r)}<div class="grow"><b>${r.title}</b><div class="muted sm">${r.reference} · ${dt(r.created_at)}</div></div>${statusChip(r.status, r.status_label)}</a>`)}</div>` : emptyState({ title: 'No requests visible', text: 'Requests assigned to other agents are hidden.' }))}</div>
    <div class="stack">${section('Assignment', html`<div class="card">${kv([['Primary agent', c.assignment.primary ? c.assignment.primary.name : '—'], ['Backup agent', c.assignment.backup ? c.assignment.backup.name : '—'], ['Assigned since', c.assignment.since ? dateOnly(c.assignment.since) : '—'], ['WhatsApp consent', c.whatsapp_consent ? 'Yes' : 'No']])}</div>`)}
      ${section('Saved locations', html`<div class="card">${c.addresses.map((a) => html`<div class="list-item">${icon('pin', 18)}<div><b>${a.label}</b><div class="muted sm">${a.locality}${a.landmark ? ' · ' + a.landmark : ''}</div></div></div>`)}</div>`)}</div></div>`;
}

// ---------------------------------------------------------------- request inbox
async function requests(ctx) {
  const scope = ctx.query.scope || 'mine';
  const me = ctx.user; const m = await meta();
  const cats = (await api('/categories')).items;
  ctx.after(() => { const t = mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/requests' + qs({ ...p, scope })), search: 'Search reference, title or customer', rowHref: (r) => '#/a/request/' + r.id,
    filters: [{ key: 'status', label: 'All statuses', options: m.statuses.map((s) => [s.key, s.label]) }, { key: 'category_id', label: 'All categories', options: cats.map((c) => [c.id, c.name]) }, { key: 'priority', label: 'Any priority', options: [['urgent', 'Urgent'], ['normal', 'Normal']] }],
    columns: [{ label: 'Request', render: (r) => html`${catIc(r, 30)} <b>${r.reference}</b> ${r.priority === 'urgent' ? chip('Urgent', 'danger') : ''}<span class="sub">${r.title}</span>` }, { label: 'Customer', render: (r) => r.customer_name }, { label: 'Area', render: (r) => r.locality },
      { label: 'Status', render: (r) => statusChip(r.status, r.status_label) }, { label: 'Age', render: ageChip }, { label: 'Quotes', render: (r) => (r.quotes_to_validate ? chip(`${r.quotes_to_validate} to validate`, 'warn') : r.quotes_total ? `${r.quotes_total} (${r.quotes_shared} shared)` : '—') },
      { label: 'Owner', render: (r) => r.agent_name || chip('Unassigned', 'warn') },
      { label: '', cls: 'act', render: (r) => (!r.assigned_agent_id ? rowBtn('claim', 'Claim', 'btn-primary btn-sm') : '') }],
    actions: { claim: async (r) => { await api(`/requests/${r.id}/assign`, { method: 'POST', body: { agent_id: me.id, reason: 'Claimed from pool' } }); toast('Request claimed.'); go('/a/request/' + r.id); } },
    empty: { ic: 'inbox', title: scope === 'pool' ? 'The pool is empty' : 'No requests in your inbox', text: 'New customer requests assigned to you show up here.' },
  }); });
  return html`${pageHeader('Request inbox', 'Triage new requests by age, locality and category.')}
    ${tabs([['mine', lead(me) ? 'All requests' : 'My requests'], ['pool', 'Unassigned pool']], scope, '#/a/requests')}<div id="tbl" class="mt"></div>`;
}

// ---------------------------------------------------------------- request detail & triage
const NEEDS_REASON = ['cancelled', 'rejected', 'expired', 'disputed'];
async function requestDetail(ctx) {
  const [r, ag] = await Promise.all([api('/requests/' + ctx.params.id), api('/agents')]);
  const me = ctx.user; const can = r.can_manage;
  ctx.on('click', '[data-status]', async (e, b) => {
    const to = b.dataset.status;
    if (NEEDS_REASON.includes(to)) { const res = await confirmDialog({ title: `Mark as ${statusInfo(to).label}?`, message: 'The customer is notified and the change is recorded in the audit trail.', confirmLabel: 'Confirm', danger: true, reason: 'required' }); if (!res) return; try { await api(`/requests/${r.id}/status`, { method: 'PATCH', body: { status: to, reason: res.reason } }); toast('Status updated.'); ctx.reload(); } catch (err) { toast(err.message, 'error'); } return; }
    act(b, async () => { await api(`/requests/${r.id}/status`, { method: 'PATCH', body: { status: to } }); toast('Status updated.'); ctx.reload(); });
  });
  ctx.on('click', '[data-act=claim]', (e, b) => act(b, async () => { await api(`/requests/${r.id}/assign`, { method: 'POST', body: { agent_id: me.id, reason: 'Claimed from pool' } }); toast('Request claimed.'); ctx.reload(); }));
  ctx.on('click', '[data-act=reassign]', () => modal({ title: 'Reassign request', submitLabel: 'Reassign', body: S(field({ name: 'agent_id', label: 'New owner', type: 'select', required: true, options: [['', 'Select an agent'], ...ag.items.filter((a) => a.id !== r.assigned_agent_id).map((a) => [a.id, `${a.name} · ${a.active_requests}/${a.capacity_limit} · ${a.availability}`])] }), field({ name: 'reason', label: 'Reason', required: true, value: 'Workload balancing' })), onSubmit: async (d) => { await api(`/requests/${r.id}/assign`, { method: 'POST', body: d }); toast('Request reassigned.'); ctx.reload(); } }));
  ctx.on('click', '[data-act=note]', () => modal({ title: 'Add internal note', submitLabel: 'Save note', body: field({ name: 'body', label: 'Note (visible to staff only)', type: 'textarea', rows: 3, required: true }).toString(), onSubmit: async (d) => { await api(`/requests/${r.id}/notes`, { method: 'POST', body: d }); toast('Note saved.'); ctx.reload(); } }));
  ctx.on('click', '[data-act=task]', () => modal({ title: 'Add follow-up', submitLabel: 'Add task', body: S(field({ name: 'title', label: 'What needs doing?', required: true, value: `Follow up on ${r.reference}` }), field({ name: 'due_at', label: 'Due', type: 'datetime-local', value: inDays(0, 17) }), field({ name: 'priority', label: 'Priority', type: 'select', options: [['normal', 'Normal'], ['high', 'High'], ['low', 'Low']] })), onSubmit: async (d) => { await api('/tasks', { method: 'POST', body: { ...d, request_id: r.id } }); toast('Task added.'); } }));
  ctx.on('click', '[data-act=invite]', async () => {
    const provs = await api(`/providers?page_size=60&category_id=${r.category.id}&status=active`);
    const invited = new Set(r.invites.map((i) => i.provider_id));
    const near = (p) => (p.areas || '').includes(r.locality) || p.locality === r.locality;
    const list = provs.items.filter((p) => !invited.has(p.id)).sort((a, b) => (near(b) - near(a)) || (b.rating_avg - a.rating_avg));
    modal({ title: 'Invite providers to quote', wide: true, submitLabel: 'Send invites', body: S(note(`Request in ${r.locality}. Providers in or near the area are listed first. Unverified providers are clearly marked.`, 'info'), `<div class="stack mt">${list.map((p) => `<label class="check card" style="padding:12px"><input type="checkbox" name="provider_ids" value="${esc(p.id)}"><span><b>${esc(p.business_name)}</b> ${p.verification_status === 'verified' ? '<span class="vbadge">✓ Verified</span>' : '<span class="chip chip-warn">Unverified</span>'}<br><span class="muted sm">${esc(p.areas || p.locality || '')} · ${p.rating_avg ? p.rating_avg + '★' : 'no reviews'} · ${p.jobs_completed} jobs ${near(p) ? '· <b style="color:var(--green-d)">near customer</b>' : ''}</span></span></label>`).join('') || '<p class="muted">No more providers for this category. Add one from the directory.</p>'}</div><div class="field-error" data-error-for="provider_ids"></div>`),
      onSubmit: async (d) => { const ids = [].concat(d.provider_ids || []); if (!ids.length) throw new ApiError(422, 'validation', 'Pick at least one provider.', { provider_ids: 'Pick at least one provider.' }); const res = await api(`/requests/${r.id}/invites`, { method: 'POST', body: { provider_ids: ids } }); toast(`${res.invited.length} provider(s) invited.`); ctx.reload(); } });
  });
  ctx.on('click', '[data-act=share]', (e, b) => act(b, async () => { await api(`/quotes/${b.dataset.id}/share`, { method: 'POST' }); toast('Quote shared with the customer.'); ctx.reload(); }));
  ctx.on('click', '[data-act=withdraw]', async (e, b) => { const x = await confirmDialog({ title: 'Withdraw this quote?', message: 'It will no longer be considered.', confirmLabel: 'Withdraw', danger: true }); if (x) { await api(`/quotes/${b.dataset.id}/withdraw`, { method: 'POST' }); toast('Quote withdrawn.'); ctx.reload(); } });
  ctx.on('click', '[data-act=nudge]', (e, b) => act(b, async () => { await api(`/requests/${r.id}/nudge`, { method: 'POST' }); toast('Reminder sent to the customer.'); ctx.reload(); }));
  ctx.on('click', '[data-act=quote-for]', async () => {
    const provs = r.invites.filter((i) => !r.quotes.some((q) => q.provider.id === i.provider_id && !['withdrawn', 'rejected', 'not_selected'].includes(q.status)));
    if (!provs.length) { toast('Every invited provider already has a quote. Invite another provider first.', 'error'); return; }
    modal({ title: 'Add a quote on behalf of a provider', wide: true, submitLabel: 'Add quote', body: S(field({ name: 'provider_id', label: 'Provider', type: 'select', required: true, options: [['', 'Select'], ...provs.map((i) => [i.provider_id, i.business_name])] }), html`<div class="grid g2">${field({ name: 'labour', label: 'Service / labour (₹)', type: 'number', required: true, min: 0 })}${field({ name: 'materials', label: 'Materials (₹)', type: 'number', min: 0, value: 0 })}</div>`, field({ name: 'scope', label: 'Scope', type: 'textarea', rows: 2, required: true, value: `${r.title} as described.` }), html`<div class="grid g3">${field({ name: 'warranty_days', label: 'Warranty (days)', type: 'number', value: 0 })}${field({ name: 'deposit_pct', label: 'Deposit %', type: 'number', value: 0 })}${field({ name: 'valid_until', label: 'Valid until', type: 'datetime-local', value: inDays(5, 18), required: true })}</div>`),
      onSubmit: async (d) => { const items = [{ description: 'Service / labour', qty: 1, unit_price: d.labour }]; if (Number(d.materials) > 0) items.push({ description: 'Materials', qty: 1, unit_price: d.materials }); await api(`/requests/${r.id}/quotes`, { method: 'POST', body: { provider_id: d.provider_id, scope: d.scope, warranty_days: d.warranty_days, deposit_pct: d.deposit_pct, valid_until: d.valid_until, items } }); toast('Quote recorded. Validate and share it when ready.'); ctx.reload(); } });
  });
  ctx.on('click', '[data-act=milestone]', () => modal({ title: 'Add milestone', body: S(field({ name: 'title', label: 'Milestone', required: true }), field({ name: 'due_date', label: 'Due date', type: 'date' })), onSubmit: async (d) => { await api(`/requests/${r.id}/milestones`, { method: 'POST', body: d }); toast('Milestone added.'); ctx.reload(); } }));
  ctx.on('change', '[data-ms]', async (e, el) => { await api('/milestones/' + el.dataset.ms, { method: 'PATCH', body: { status: el.value } }); toast('Milestone updated.'); });
  ctx.on('click', '[data-act=open-file]', (e, b) => openFile(b.dataset.id));
  ctx.on('click', '[data-act=priority]', (e, b) => act(b, async () => { await api('/requests/' + r.id, { method: 'PATCH', body: { priority: r.priority === 'urgent' ? 'normal' : 'urgent' } }); ctx.reload(); }));
  const live = !['completed', 'cancelled', 'rejected', 'expired'].includes(r.status);
  return html`<a href="#/a/requests" class="muted sm">← Request inbox</a>
    ${pageHeader(html`${r.category.icon} ${r.reference} · ${r.title}`, html`${r.customer.name} · ${phone(r.customer.mobile)} · ${r.locality} · created ${ago(r.created_at)}`, html`${statusChip(r.status, r.status_label)} ${r.priority === 'urgent' ? chip('Urgent', 'danger') : ''}${!r.assigned_agent_id ? html`<button class="btn btn-primary" data-act="claim">Claim request</button>` : ''}${can && lead(me) ? html`<button class="btn btn-ghost" data-act="reassign">Reassign</button>` : ''}`)}
    ${!can && r.assigned_agent_id ? note(`Assigned to ${r.agent ? r.agent.name : 'another agent'} — you have read access only.`, 'warn') : ''}
    ${can && live ? html`<div class="card card-soft mb"><div class="row between wrap"><div><b>Move this request forward</b><div class="muted sm">${r.status_next}</div></div><div class="row-gap">${r.allowed_transitions.map((s) => html`<button class="btn ${NEEDS_REASON.includes(s) ? 'btn-ghost' : 'btn-primary'} btn-sm" data-status="${s}">${NEEDS_REASON.includes(s) ? 'Mark ' : '→ '}${statusInfo(s).label}</button>`)}${r.status === 'awaiting_approval' ? html`<button class="btn btn-secondary btn-sm" data-act="nudge">Nudge customer</button>` : ''}<button class="btn btn-ghost btn-sm" data-act="priority">${r.priority === 'urgent' ? 'Remove urgent' : 'Mark urgent'}</button></div></div></div>` : ''}
    <div class="split"><div class="stack">
      <div class="card"><h2 class="mb">Request</h2><p>${r.description}</p>${kv([...r.details.map((d) => [d.label, d.value]), ['Address', r.address ? `${r.address.line1}, ${r.address.locality}${r.address.landmark ? ' (' + r.address.landmark + ')' : ''}` : r.locality], ['Preferred', r.preferred_at ? dtl(r.preferred_at) : 'Flexible'], ['Budget', r.budget_min || r.budget_max ? `${r.budget_min ? inr(r.budget_min) : '—'} – ${r.budget_max ? inr(r.budget_max) : '—'}` : null]])}
        ${r.brief ? html`<hr class="divider">${kv([['Event', r.brief.event_type], ['Date', r.brief.event_date], ['Venue', r.brief.venue], ['Guests', r.brief.guest_count], ['Services', r.brief.services], ['Coverage', r.brief.coverage_hours ? r.brief.coverage_hours + ' hrs ' + (r.brief.coverage_style || '') : null], ['Deliverables', r.brief.deliverables], ['Notes', r.brief.notes]])}` : ''}${r.attachments.length ? html`<div class="row-gap mt">${r.attachments.map((a) => html`<button class="attach" data-act="open-file" data-id="${a.id}">${icon('paperclip', 14)} ${a.filename}</button>`)}</div>` : ''}</div>
      <div class="card"><div class="row between mb"><h2>Providers</h2>${can && live && !['confirmed', 'in_progress'].includes(r.status) ? html`<button class="btn btn-secondary btn-sm" data-act="invite">${icon('plus', 16)} Invite providers</button>` : ''}</div>
        ${r.invites.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Invite</th><th>Rating</th><th>Sent</th></tr></thead><tbody>${r.invites.map((i) => html`<tr><td data-label="Provider"><b>${i.business_name}</b> ${verified(i.verification_status)}</td><td data-label="Invite">${chip(cap(i.status), i.status === 'quoted' ? 'success' : i.status === 'declined' ? 'neutral' : 'info')}${i.decline_reason ? html`<span class="sub">${i.decline_reason}</span>` : ''}</td><td data-label="Rating">${i.rating_avg || '—'}</td><td data-label="Sent">${ago(i.created_at)}</td></tr>`)}</tbody></table></div>` : html`<p class="muted">No providers invited yet. Choose verified providers near ${r.locality}.</p>`}</div>
      <div class="card"><div class="row between mb"><h2>Quotes</h2><div class="row-gap">${r.quotes.length > 1 ? html`<a class="btn btn-ghost btn-sm" href="#/a/compare/${r.id}">Compare side by side</a>` : ''}${can && live && ['under_review', 'finding_providers', 'quotes_received', 'awaiting_approval'].includes(r.status) ? html`<button class="btn btn-ghost btn-sm" data-act="quote-for">Add quote for provider</button>` : ''}</div></div>
        ${r.quotes.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th class="num">Total</th><th>Status</th><th>Valid until</th><th></th></tr></thead><tbody>${r.quotes.map((q) => html`<tr><td data-label="Provider"><b>${q.provider.business_name}</b> ${verified(q.provider.verification_status)}<span class="sub">${q.items.length} items · v${q.version}</span></td><td class="num" data-label="Total">${inr(q.total)}</td><td data-label="Status">${qChip(q.status)}</td><td data-label="Valid">${dt(q.valid_until)}</td><td class="act">${can && q.status === 'submitted' ? html`<button class="btn btn-primary btn-sm" data-act="share" data-id="${q.id}">Validate & share</button>` : ''}${can && ['submitted', 'shared', 'clarification_requested'].includes(q.status) ? html`<button class="btn btn-ghost btn-sm" data-act="withdraw" data-id="${q.id}">Withdraw</button>` : ''}</td></tr>${q.status === 'clarification_requested' ? html`<tr><td colspan="5"><div class="note note-info">Customer asked: “${q.clarification_note}”</div></td></tr>` : ''}`)}</tbody></table></div>` : html`<p class="muted">No quotes yet.</p>`}</div>
      ${r.milestones.length || r.brief ? html`<div class="card"><div class="row between mb"><h2>Milestones</h2>${can ? html`<button class="btn btn-ghost btn-sm" data-act="milestone">Add</button>` : ''}</div>${r.milestones.map((m) => html`<div class="list-item"><div class="grow"><b>${m.title}</b><div class="muted sm">${m.due_date || ''} ${m.provider_name ? '· ' + m.provider_name : ''}</div></div>${can ? html`<select data-ms="${m.id}" style="width:auto;min-height:36px" aria-label="Milestone status">${opts([['pending', 'Pending'], ['in_progress', 'In progress'], ['done', 'Done']], m.status)}</select>` : chip(cap(m.status))}</div>`)}</div>` : ''}
    </div><div class="stack">
      ${r.booking ? html`<div class="card"><h2 class="mb">Booking</h2>${kv([['Reference', r.booking.reference], ['Provider', r.booking.provider.business_name], ['Status', bChip(r.booking.status)], ['Amount', inr(r.booking.amount)], ['Paid', inr(r.booking.paid_amount)]])}<a class="btn btn-secondary btn-block mt" href="#/a/booking/${r.booking.id}">Coordinate booking</a></div>` : ''}
      <div class="card"><h2 class="mb">Timeline</h2>${requestTimeline(r.history, r.status)}</div>
      <div class="card"><div class="row between mb"><h2>Internal notes</h2><div class="row-gap"><button class="btn btn-ghost btn-sm" data-act="task">+ Task</button>${can ? html`<button class="btn btn-ghost btn-sm" data-act="note">+ Note</button>` : ''}</div></div>${r.notes.length ? r.notes.map((n) => html`<div style="padding:8px 0;border-bottom:1px solid var(--line)"><p style="margin:0">${n.body}</p><span class="muted xs">${n.author} · ${ago(n.created_at)}</span></div>`) : html`<p class="muted">No notes yet.</p>`}</div>
      <div class="card"><h2 class="mb">Ownership</h2>${kv([['Owner', r.agent ? r.agent.name : 'Unassigned']])}${r.assignment_history.map((h) => html`<div class="muted sm" style="padding:4px 0">${ago(h.changed_at)} · ${h.from_name || '—'} → ${h.to_name || '—'} <span class="xs">(${h.reason})</span></div>`)}</div></div></div>`;
}

// ---------------------------------------------------------------- providers
async function providers(ctx) {
  const [cats, m] = await Promise.all([api('/categories'), meta()]);
  ctx.on('click', '[data-act=add]', () => modal({ title: 'Add provider to directory', wide: true, submitLabel: 'Add provider', body: S(note('Providers added by agents start as <b>unverified</b> and are never shown as verified until documents are reviewed.', 'info'), '<div class="mt"></div>', field({ name: 'business_name', label: 'Business / person name', required: true }), html`<div class="grid g2">${field({ name: 'phone', label: 'Mobile', type: 'tel', prefix: '+91', required: true })}${field({ name: 'locality', label: 'Main locality', type: 'select', required: true, options: [['', 'Select'], ...m.localities] })}${field({ name: 'type', label: 'Type', type: 'select', options: [['business', 'Business'], ['individual', 'Individual']] })}${field({ name: 'kind', label: 'Specialisation', type: 'select', options: [['general', 'General'], ['catering', 'Catering'], ['photography', 'Photography']] })}</div>`, `<div class="field"><label>Categories <span class="req">*</span></label><div class="chips-pick">${cats.items.filter((c) => c.is_active).map((c) => `<label><input type="checkbox" name="category_ids" value="${esc(c.id)}"><span>${esc(c.name)}</span></label>`).join('')}</div><div class="field-error" data-error-for="category_ids"></div></div>`),
    onSubmit: async (d) => { await api('/providers', { method: 'POST', body: { ...d, category_ids: [].concat(d.category_ids || []) } }); toast('Provider added to the directory.'); ctx.reload(); } }));
  const showProfile = async (id) => {
    const p = await api('/providers/' + id);
    modal({ title: p.business_name, wide: true, footer: false, body: S(`<div class="row-gap" style="gap:8px">${verified(p.verification_status).toString()} ${chip(cap(p.status), p.status === 'active' ? 'success' : 'danger')} ${chip(cap(p.source.replace('_', ' ')))}</div><div class="split mt"><div>${kv([['Phone', p.phone ? phone(p.phone) : '—'], ['Locality', p.locality], ['Rating', p.rating_avg ? `${p.rating_avg} (${p.rating_count} reviews)` : 'No reviews'], ['Jobs completed', p.jobs_completed], ['Response rate', p.response_rate + '%'], ['Service areas', p.areas.join(', ')]]).toString()}</div><div><h3 class="mb">Services</h3>${p.services.slice(0, 8).map((s) => `<div class="row between sm" style="padding:3px 0"><span>${esc(s.icon)} ${esc(s.name)}</span><b>${esc(inr(s.base_price))}</b></div>`).join('') || '<p class="muted">None</p>'}</div></div>
      <h3 class="mt mb">Documents</h3>${p.documents.map((d) => `<div class="row between sm" style="padding:3px 0"><span>${esc(cap(d.doc_type))}</span><span class="chip chip-${d.status === 'verified' ? 'success' : d.status === 'pending' ? 'warn' : 'danger'}">${esc(d.status)}</span></div>`).join('') || '<p class="muted">No documents on file.</p>'}
      <h3 class="mt mb">Recent contact</h3>${p.recent_contacts.map((c) => `<div class="sm" style="padding:3px 0">${esc(ago(c.created_at))} · ${esc(cap(c.channel))} · ${esc(c.outcome || '')} <span class="muted">${esc(c.notes || '')}</span></div>`).join('') || '<p class="muted">No outreach logged.</p>'}
      <div class="row-gap mt">${ctx.query.request ? `<button class="btn btn-primary" data-invite-this>Invite to ${esc(ctx.query.request_ref || 'request')}</button>` : ''}${p.user_id ? '<button class="btn btn-secondary" data-chat-this>Message in app</button>' : ''}<a class="btn btn-ghost" href="#/a/outreach?provider=${esc(p.id)}">Log a call</a></div>`),
      onMount: (mm, close) => {
        mm.querySelector('[data-invite-this]')?.addEventListener('click', async () => { try { await api(`/requests/${ctx.query.request}/invites`, { method: 'POST', body: { provider_ids: [p.id] } }); toast('Invited.'); close(); go('/a/request/' + ctx.query.request); } catch (e) { toast(e.message, 'error'); } });
        mm.querySelector('[data-chat-this]')?.addEventListener('click', async () => { try { const c = await api('/conversations', { method: 'POST', body: { provider_id: p.id } }); close(); go('/a/messages?c=' + c.id); } catch (e) { toast(e.message, 'error'); } });
      } });
  };
  ctx.after(() => { mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/providers' + qs(p)), search: 'Search by name or phone', pageSize: 12,
    filters: [{ key: 'category_id', label: 'All categories', options: cats.items.map((c) => [c.id, c.name]) }, { key: 'locality', label: 'Any locality', options: m.localities.map((l) => [l, l]) }, { key: 'verification_status', label: 'Any verification', options: [['verified', 'Verified'], ['pending', 'Pending'], ['unverified', 'Unverified'], ['rejected', 'Rejected']] }],
    columns: [{ label: 'Provider', render: (p) => html`<div class="row">${avatar(p.business_name, p.logo_color, 34)}<div><b>${p.business_name}</b><span class="sub">${p.categories || ''}</span></div></div>` }, { label: 'Verification', render: (p) => verified(p.verification_status) }, { label: 'Area', render: (p) => p.locality }, { label: 'Rating', render: (p) => (p.rating_avg ? html`${icon('star', 13)} ${p.rating_avg} (${p.rating_count})` : '—') }, { label: 'Jobs', cls: 'num', render: (p) => p.jobs_completed },
      { label: 'Status', render: (p) => chip(cap(p.status), p.status === 'active' ? 'success' : 'danger') }, { label: '', cls: 'act', render: () => rowBtn('open', 'View') }],
    actions: { open: (p) => showProfile(p.id) }, empty: { ic: 'tool', title: 'No providers match', text: 'Add a provider or relax the filters.' },
  }); if (ctx.query.open) showProfile(ctx.query.open); });
  return html`${pageHeader('Provider directory', 'Internal sourcing directory for manual and registered vendors.', html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} Add provider</button>`)}${ctx.query.request ? note('Choose a provider and press “Invite” to send them this request.', 'info') : ''}<div id="tbl" class="mt"></div>`;
}

async function outreach(ctx) {
  const [reqs, provs] = await Promise.all([api('/requests?page_size=50&status_group=open'), api('/providers?page_size=100&status=active')]);
  ctx.submit('#f-log', async (d) => { await api('/contact-log', { method: 'POST', body: { party_type: 'provider', party_id: d.party_id, channel: d.channel, outcome: d.outcome, notes: d.notes, request_id: d.request_id || undefined, direction: d.direction } }); toast('Outreach logged.'); ctx.reload(); });
  ctx.after(() => mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/contact-log' + qs({ ...p, party_type: 'provider' })), search: false, pageSize: 10,
    columns: [{ label: 'When', render: (l) => html`${dt(l.created_at)}<span class="sub">${ago(l.created_at)}</span>` }, { label: 'Provider', render: (l) => l.party_name }, { label: 'Request', render: (l) => l.reference || '—' }, { label: 'Channel', render: (l) => chip(cap(l.channel)) }, { label: 'Outcome', render: (l) => html`<b>${l.outcome || ''}</b><span class="sub">${l.notes || ''}</span>` }],
    empty: { ic: 'phone', title: 'No outreach logged', text: 'Record calls and WhatsApp messages so the history is auditable.' },
  }));
  return html`${pageHeader('Provider outreach log', 'Record calls and WhatsApp outreach as auditable actions.')}
    <div class="split"><form id="f-log" class="card" novalidate><h2 class="mb">Log outreach</h2>${field({ name: 'party_id', label: 'Provider', type: 'select', required: true, value: ctx.query.provider || '', options: [['', 'Select provider'], ...provs.items.map((p) => [p.id, p.business_name])] })}${field({ name: 'request_id', label: 'Request (optional)', type: 'select', options: [['', 'Not linked'], ...reqs.items.map((r) => [r.id, `${r.reference} · ${r.title}`])] })}
      <div class="grid g2">${field({ name: 'channel', label: 'Channel', type: 'select', options: [['call', 'Phone call'], ['whatsapp', 'WhatsApp'], ['sms', 'SMS'], ['email', 'Email']] })}${field({ name: 'direction', label: 'Direction', type: 'select', options: [['outbound', 'Outbound'], ['inbound', 'Inbound']] })}</div>
      ${field({ name: 'outcome', label: 'Outcome', required: true, placeholder: 'e.g. Accepted - will quote today' })}${field({ name: 'notes', label: 'Notes', type: 'textarea', rows: 2 })}<div class="form-error" role="alert" hidden></div><button class="btn btn-primary" type="submit">Save log entry</button></form>
    <div id="tbl"></div></div>`;
}

// ---------------------------------------------------------------- quotes
async function quotes(ctx) {
  ctx.after(() => mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/quotes' + qs(p)), search: false, filters: [{ key: 'status', label: 'All statuses', options: Object.entries(QS).map(([k, v]) => [k, v[0]]) }], rowHref: (q) => '#/a/compare/' + q.request_id,
    columns: [{ label: 'Request', render: (q) => html`<b>${q.reference}</b><span class="sub">${q.title}</span>` }, { label: 'Provider', render: (q) => html`${q.provider_name} ${verified(q.verification_status)}` }, { label: 'Quote', cls: 'num', render: (q) => inr(q.total) }, { label: 'Status', render: (q) => qChip(q.status) }, { label: 'Valid until', render: (q) => dt(q.valid_until) }, { label: 'Updated', render: (q) => ago(q.updated_at) }],
    empty: { ic: 'file', title: 'No quotes yet', text: 'Quotes from providers on your requests appear here for validation.' },
  }));
  return html`${pageHeader('Quote comparison & validation', 'Review provider quotes before sharing them with the customer.')}<div id="tbl"></div>`;
}

async function compare(ctx) {
  const r = await api('/requests/' + ctx.params.id);
  const qs_ = r.quotes.filter((q) => !['withdrawn'].includes(q.status));
  const best = qs_.length ? Math.min(...qs_.map((q) => q.total)) : 0;
  ctx.on('click', '[data-act=share]', (e, b) => act(b, async () => { await api(`/quotes/${b.dataset.id}/share`, { method: 'POST' }); toast('Shared with the customer.'); ctx.reload(); }));
  ctx.on('click', '[data-act=withdraw]', async (e, b) => { const x = await confirmDialog({ title: 'Withdraw this quote?', message: 'It will be removed from consideration.', confirmLabel: 'Withdraw', danger: true }); if (x) { await api(`/quotes/${b.dataset.id}/withdraw`, { method: 'POST' }); ctx.reload(); } });
  const row = (label, fn) => html`<tr><th scope="row" style="white-space:nowrap">${label}</th>${qs_.map((q) => html`<td class="${q.total === best ? 'best-col' : ''}">${fn(q)}</td>`)}</tr>`;
  return html`<a href="#/a/request/${r.id}" class="muted sm">← ${r.reference}</a>${pageHeader(`Compare quotes — ${r.title}`, `${r.customer.name} · ${r.locality}`)}
    ${qs_.length ? html`<div class="card compare"><table class="table"><thead><tr><th></th>${qs_.map((q) => html`<th class="${q.total === best ? 'best-col' : ''}">${q.provider.business_name}</th>`)}</tr></thead><tbody>
      ${row('Price', (q) => html`<span class="price-big" style="font-size:20px">${inr(q.total)}</span> ${q.total === best && qs_.length > 1 ? chip('Lowest', 'success') : ''}`)}${row('Status', (q) => qChip(q.status))}${row('Verification', (q) => verified(q.provider.verification_status))}${row('Rating', (q) => (q.provider.rating_avg ? html`${icon('star', 13)} ${q.provider.rating_avg} (${q.provider.rating_count})` : '—'))}${row('Jobs done', (q) => q.provider.jobs_completed)}
      ${row('Scope', (q) => q.scope)}${row('Line items', (q) => html`${q.items.map((i) => html`<div class="xs">${i.description}: ${inr(i.amount)}</div>`)}`)}${row('Not included', (q) => q.exclusions || '—')}${row('Warranty', (q) => (q.warranty_days ? q.warranty_days + ' days' : 'None'))}${row('Deposit', (q) => (q.deposit_pct ? `${q.deposit_pct}% (${inr(q.deposit_amount)})` : 'None'))}${row('Availability', (q) => (q.est_start_at ? dt(q.est_start_at) : '—'))}${row('Valid until', (q) => dt(q.valid_until))}
      ${row('Action', (q) => html`${q.status === 'submitted' && r.can_manage ? html`<button class="btn btn-primary btn-sm" data-act="share" data-id="${q.id}">Validate & share</button>` : ''}${['submitted', 'shared'].includes(q.status) && r.can_manage ? html` <button class="btn btn-ghost btn-sm" data-act="withdraw" data-id="${q.id}">Withdraw</button>` : ''}`)}</tbody></table></div>
      ${note('Check scope, exclusions and validity before sharing. The customer sees only validated quotes and must approve explicitly before any booking is created.', 'info')}` : emptyState({ ic: 'file', title: 'No quotes to compare', text: 'Invite providers from the request page.', action: html`<a class="btn btn-primary" href="#/a/request/${r.id}">Open request</a>` })}`;
}

async function approvals(ctx) {
  const d = await api('/agent/approvals');
  ctx.on('click', '[data-nudge]', (e, b) => act(b, async () => { await api(`/requests/${b.dataset.nudge}/nudge`, { method: 'POST' }); toast('Reminder sent.'); }));
  return html`${pageHeader('Customer approval queue', 'Customer decision is a hard gate — never convert a quote to a booking without approval.')}
    ${d.items.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>Request</th><th>Customer</th><th class="num">Quotes</th><th class="num">Best price</th><th>Waiting</th><th></th></tr></thead><tbody>${d.items.map((a) => html`<tr class="clickable" data-href="#/a/request/${a.request_id}"><td data-label="Request"><b>${a.reference}</b><span class="sub">${a.title}</span></td><td data-label="Customer">${a.customer_name}<span class="sub">${phone(a.customer_mobile)}</span></td><td class="num" data-label="Quotes">${a.quotes_open}${a.questions ? html` <span class="chip chip-warn">${a.questions} question</span>` : ''}</td><td class="num" data-label="Best">${inr(a.best_price)}</td><td data-label="Waiting">${a.waiting_hours > 24 ? chip(hoursText(a.waiting_hours), 'danger') : hoursText(a.waiting_hours)}</td><td class="act"><button class="btn btn-secondary btn-sm" data-nudge="${a.request_id}">Nudge</button> <a class="btn btn-ghost btn-sm" href="#/a/request/${a.request_id}">Open</a></td></tr>`)}</tbody></table></div>` : emptyState({ ic: 'check', title: 'Nothing waiting for approval', text: 'When you share quotes, customers appear here until they decide.' })}`;
}

// ---------------------------------------------------------------- bookings & tracking
async function bookings(ctx) {
  const tab = ctx.query.tab || 'upcoming';
  ctx.after(() => mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/bookings' + qs({ ...p, group: tab })), search: 'Search booking, customer or provider', rowHref: (b) => '#/a/booking/' + b.id,
    columns: [{ label: 'Booking', render: (b) => html`<b>${b.reference}</b><span class="sub">${b.title} · ${b.request_reference}</span>` }, { label: 'Customer', render: (b) => b.customer_name }, { label: 'Provider', render: (b) => b.provider_name }, { label: 'Scheduled', render: (b) => (b.scheduled_at ? dt(b.scheduled_at) : 'TBC') },
      { label: 'Payment', render: (b) => chip(b.payment_status === 'paid' ? 'Paid' : b.payment_status === 'deposit_paid' ? 'Deposit' : cap(b.payment_status), b.payment_status === 'paid' ? 'success' : 'neutral') }, { label: 'Status', render: (b) => bChip(b.status) }],
    empty: { ic: 'briefcase', title: `No ${tab} bookings`, text: 'Bookings appear once customers approve quotes.' },
  }));
  return html`${pageHeader('Booking coordination', 'Confirm vendor, slot, payment and customer expectations.')}${tabs([['upcoming', 'Upcoming'], ['attention', 'Needs attention'], ['completed', 'Completed'], ['cancelled', 'Cancelled']], tab, '#/a/bookings')}<div id="tbl" class="mt"></div>`;
}

async function bookingDetail(ctx) {
  const b = await api('/bookings/' + ctx.params.id);
  ctx.on('click', '[data-act=cash]', () => modal({ title: 'Record offline payment', submitLabel: 'Record payment', body: S(note(`Outstanding: ${inr(b.amount - b.paid_amount)}. Use this when the customer paid in cash or by direct transfer.`, 'info'), field({ name: 'kind', label: 'Applies to', type: 'select', options: [['balance', 'Balance / remaining'], ['deposit', 'Deposit']] })), onSubmit: async (d) => { await api(`/bookings/${b.id}/pay`, { method: 'POST', body: { kind: b.paid_amount ? 'balance' : d.kind === 'deposit' ? 'deposit' : 'full', method: 'cash' } }); toast('Payment recorded.'); ctx.reload(); } }));
  ctx.on('click', '[data-act=cancel]', async () => { const x = await confirmDialog({ title: 'Cancel this booking?', message: 'The request is cancelled, the provider is notified and a refund request is raised if the customer paid.', confirmLabel: 'Cancel booking', danger: true, reason: 'required' }); if (x) { try { await api(`/bookings/${b.id}/cancel`, { method: 'POST', body: { reason: x.reason } }); toast('Booking cancelled.'); ctx.reload(); } catch (e) { toast(e.message, 'error'); } } });
  ctx.on('click', '[data-act=complete]', async () => { const x = await confirmDialog({ title: 'Complete on behalf of customer?', message: 'Only do this if the customer confirmed by phone and payment is settled.', confirmLabel: 'Mark completed', reason: 'required', reasonLabel: 'How did the customer confirm?' }); if (x) { try { await api(`/requests/${b.request_id}/complete`, { method: 'POST', body: { reason: x.reason } }); toast('Completed.'); ctx.reload(); } catch (e) { toast(e.message, 'error'); } } });
  ctx.on('click', '[data-move]', (e, el) => act(el, async () => { await api(`/bookings/${b.id}/status`, { method: 'PATCH', body: { status: el.dataset.move, note: el.dataset.move === 'work_done' ? 'Marked done by agent after provider confirmation' : undefined } }); toast('Updated.'); ctx.reload(); }));
  const nxt = { confirmed: [['on_the_way', 'Provider on the way'], ['in_progress', 'Job started']], on_the_way: [['in_progress', 'Job started']], in_progress: [['work_done', 'Work done']] }[b.status] || [];
  return html`<a href="#/a/bookings" class="muted sm">← Bookings</a>${pageHeader(`${b.reference} · ${b.title}`, `Request ${b.request_reference} · ${b.provider_name}`, html`${bChip(b.status)}`)}
    <div class="split"><div class="stack"><div class="card"><h2 class="mb">Coordination checklist</h2>${timeline([{ title: 'Customer approved quote', state: 'done', time: dt(b.created_at) }, { title: b.paid_amount ? `Payment received (${inr(b.paid_amount)})` : 'Collect deposit / payment', state: b.paid_amount ? 'done' : 'current' }, { title: `Slot ${b.scheduled_at ? dtl(b.scheduled_at) : 'to be confirmed'}`, state: b.scheduled_at ? 'done' : 'current' }, { title: 'Provider executes the job', state: ['in_progress', 'work_done', 'completed'].includes(b.status) ? 'done' : 'pending' }, { title: 'Customer confirms completion', state: b.status === 'completed' ? 'done' : 'pending' }])}</div>
      <div class="card"><h2 class="mb">Activity</h2>${timeline(b.events.map((e) => ({ title: cap(e.event.replace('_', ' ')), time: dt(e.created_at), note: e.detail })))}</div></div>
    <div class="stack"><div class="card"><h2 class="mb">Parties</h2>${kv([['Customer', html`${b.customer_name} ${b.customer_phone ? html`<a href="tel:${b.customer_phone}">${phone(b.customer_phone)}</a>` : ''}`], ['Provider', html`${b.provider_name} ${b.provider_phone ? html`<a href="tel:${b.provider_phone}">${phone(b.provider_phone)}</a>` : ''}`], ['Where', b.address ? `${b.address.line1}, ${b.address.locality}` : b.locality]])}</div>
      <div class="card"><h2 class="mb">Money</h2>${kv([['Total', inr(b.amount)], ['Deposit', inr(b.deposit_amount)], ['Paid', inr(b.paid_amount)], ['Balance', inr(b.amount - b.paid_amount)]])}${b.refund ? html`<div class="note note-info mt">Refund ${b.refund.status}: ${inr(b.refund.amount)}</div>` : ''}</div>
      ${!['completed', 'cancelled'].includes(b.status) ? html`<div class="card card-soft"><h3 class="mb">Actions</h3><div class="stack">${nxt.map(([s, l]) => html`<button class="btn btn-secondary btn-block" data-move="${s}">${l}</button>`)}${b.amount > b.paid_amount ? html`<button class="btn btn-secondary btn-block" data-act="cash">Record offline payment</button>` : ''}<button class="btn btn-primary btn-block" data-act="complete">Complete on behalf of customer</button><button class="btn btn-danger-o btn-block" data-act="cancel">Cancel booking</button></div></div>` : ''}<a class="btn btn-ghost btn-block" href="#/a/request/${b.request_id}">Open request</a></div></div>`;
}

async function tracking(ctx) {
  const d = await api('/agent/tracking');
  const cols = [['confirmed', 'Confirmed'], ['on_the_way', 'On the way'], ['in_progress', 'In progress'], ['work_done', 'Awaiting customer'], ['pending_reconsent', 'Re-approval'], ['disputed', 'Disputed']];
  return html`${pageHeader('Live job tracking', 'Monitor fulfilment and resolve exceptions.')}
    ${d.exceptions.length ? html`<div class="card mb" style="border-color:var(--warn)"><h2 class="mb">${icon('alert', 18)} ${d.exceptions.length} exception${d.exceptions.length > 1 ? 's' : ''} need attention</h2>${d.exceptions.map((b) => html`<a class="list-item" href="#/a/booking/${b.id}">${catIc(b, 34)}<div class="grow"><b>${b.request_reference}</b> · ${b.provider_name}<div class="muted sm">${b.exception}</div></div>${icon('right', 18, 'chev')}</a>`)}</div>` : note('No exceptions — all live jobs are on track.', 'success')}
    <div class="board mt">${cols.map(([k, l]) => { const items = d.items.filter((b) => b.status === k); return html`<div class="board-col"><h3>${l}<span>${items.length}</span></h3>${items.map((b) => html`<a class="board-card card-link" href="#/a/booking/${b.id}" style="display:block;color:inherit;text-decoration:none"><b>${b.title}</b><div class="muted sm">${b.request_reference} · ${b.customer_name}</div><div class="sm">${b.provider_name}</div><div class="muted xs">${b.scheduled_at ? dt(b.scheduled_at) : 'TBC'}</div>${b.exception ? html`<span class="warn">${b.exception}</span>` : ''}</a>`)}${items.length ? '' : html`<p class="muted xs center">Nothing here</p>`}</div>`; })}</div>`;
}

// ---------------------------------------------------------------- tasks
async function tasks(ctx) {
  const tab = ctx.query.tab || 'open';
  const t = await api('/tasks?page_size=100&status=' + tab);
  ctx.on('change', '[data-done]', async (e, el) => { await api('/tasks/' + el.dataset.done, { method: 'PATCH', body: { status: el.checked ? 'done' : 'open' } }); toast(el.checked ? 'Task completed.' : 'Task reopened.'); ctx.reload(); });
  ctx.on('click', '[data-del]', async (e, b) => { await api('/tasks/' + b.dataset.del, { method: 'DELETE' }); ctx.reload(); });
  ctx.on('click', '[data-act=add]', () => modal({ title: 'Add follow-up', submitLabel: 'Add task', body: S(field({ name: 'title', label: 'What needs doing?', required: true }), field({ name: 'due_at', label: 'Due', type: 'datetime-local', value: inDays(0, 17) }), field({ name: 'priority', label: 'Priority', type: 'select', options: [['normal', 'Normal'], ['high', 'High'], ['low', 'Low']] })), onSubmit: async (d) => { await api('/tasks', { method: 'POST', body: d }); toast('Task added.'); ctx.reload(); } }));
  return html`${pageHeader('Follow-ups & tasks', 'Organise reminders and follow-through.', html`<button class="btn btn-primary" data-act="add">${icon('plus', 18)} Add task</button>`)}${tabs([['open', 'Open'], ['done', 'Completed']], tab, '#/a/tasks')}
    <div class="mt">${t.items.length ? html`<div class="card" style="padding:4px 16px">${t.items.map((x) => html`<div class="list-item"><label class="check"><input type="checkbox" data-done="${x.id}" ${x.status === 'done' ? 'checked' : ''} aria-label="Complete ${x.title}"><span></span></label><div class="grow"><b style="${x.status === 'done' ? 'text-decoration:line-through;color:var(--muted)' : ''}">${x.title}</b><div class="muted sm">${x.reference ? html`<a href="#/a/request/${x.request_id}">${x.reference}</a> · ` : ''}${x.customer_name ? x.customer_name + ' · ' : ''}${x.due_at ? (x.overdue ? 'Overdue ' : 'Due ') + dt(x.due_at) : 'No due date'}</div></div>${x.priority === 'high' ? chip('High', 'danger') : ''}${x.overdue ? chip('Overdue', 'danger') : ''}<button class="icon-btn" data-del="${x.id}" aria-label="Delete task">${icon('trash', 18)}</button></div>`)}</div>` : emptyState({ ic: 'clock', title: tab === 'open' ? 'No open tasks' : 'Nothing completed yet', text: 'Add reminders so nothing slips through.' })}</div>`;
}

// ---------------------------------------------------------------- messages & call log
async function messages(ctx) {
  const tab = ctx.query.tab || 'chat';
  if (tab === 'calls') {
    const reqs = await api('/requests?page_size=50&status_group=open');
    ctx.on('click', '[data-act=log]', () => modal({ title: 'Log a call or message', submitLabel: 'Save', body: S(field({ name: 'request_id', label: 'Request', type: 'select', required: true, options: [['', 'Select'], ...reqs.items.map((r) => [r.id, `${r.reference} · ${r.customer_name}`])] }), html`<div class="grid g2">${field({ name: 'channel', label: 'Channel', type: 'select', options: [['call', 'Call'], ['whatsapp', 'WhatsApp'], ['sms', 'SMS']] })}${field({ name: 'direction', label: 'Direction', type: 'select', options: [['outbound', 'Outbound'], ['inbound', 'Inbound']] })}</div>`, field({ name: 'outcome', label: 'Outcome', required: true }), field({ name: 'notes', label: 'Notes', type: 'textarea', rows: 2 })), onSubmit: async (d) => { await api('/contact-log', { method: 'POST', body: { ...d, party_type: 'customer' } }); toast('Logged.'); ctx.reload(); } }));
    ctx.after(() => mountTable(ctx.view.querySelector('#tbl'), { load: (p) => api('/contact-log' + qs(p)), search: false, filters: [{ key: 'party_type', label: 'Customers & providers', options: [['customer', 'Customers'], ['provider', 'Providers']] }, { key: 'channel', label: 'All channels', options: [['call', 'Call'], ['whatsapp', 'WhatsApp'], ['sms', 'SMS'], ['email', 'Email']] }],
      columns: [{ label: 'When', render: (l) => dt(l.created_at) }, { label: 'Who', render: (l) => html`${l.party_name} ${chip(cap(l.party_type))}` }, { label: 'Request', render: (l) => l.reference || '—' }, { label: 'Channel', render: (l) => `${cap(l.channel)} · ${l.direction}` }, { label: 'Outcome', render: (l) => html`<b>${l.outcome || ''}</b><span class="sub">${l.notes || ''}</span>` }], empty: { ic: 'phone', title: 'No contact history', text: 'Calls and messages you log appear here.' } }));
    return html`${pageHeader('Messages & call log', 'Unified contact history for every request.', html`<button class="btn btn-primary" data-act="log">Log a call</button>`)}${tabs([['chat', 'Messages'], ['calls', 'Call & outreach log']], tab, '#/a/messages')}<div id="tbl" class="mt"></div>`;
  }
  const list = await api('/conversations');
  const cur = ctx.query.c ? list.items.find((c) => c.id === ctx.query.c) : list.items[0];
  const me = ctx.user.id; let pending = null;
  if (cur) {
    const load = async () => { const r = await api(`/conversations/${cur.id}/messages`); const box = ctx.view.querySelector('#chat-box'); if (!box) return; const near = box.scrollHeight - box.scrollTop - box.clientHeight < 140; box.innerHTML = chat(r.items, me).toString(); if (near) box.scrollTop = box.scrollHeight; };
    ctx.after(async () => { await load(); const b = ctx.view.querySelector('#chat-box'); b && (b.scrollTop = b.scrollHeight); }); ctx.every(() => load().catch(() => {}), 6000);
    ctx.submit('[data-chat-form]', async (d, f) => { if (!d.body.trim() && !pending) return; await api(`/conversations/${cur.id}/messages`, { method: 'POST', body: { body: d.body.trim(), attachment_id: pending ? pending.id : undefined } }); pending = null; f.reset(); await load(); });
    ctx.on('change', '[data-chat-file]', async (e, el) => { if (el.files[0]) { try { pending = await upload(el.files[0]); toast('Attachment ready — press send.'); } catch (err) { toast(err.message, 'error'); } el.value = ''; } });
    ctx.on('click', '[data-act=open-file]', (e, b) => openFile(b.dataset.id));
  }
  return html`${pageHeader('Messages & call log', 'Customer and provider conversations in one place.')}${tabs([['chat', 'Messages'], ['calls', 'Call & outreach log']], tab, '#/a/messages')}
    ${list.items.length ? html`<div class="split mt" style="grid-template-columns:minmax(240px,.8fr) 2fr"><div class="card" style="padding:4px 12px">${list.items.map((c) => html`<a class="list-item" href="#/a/messages?c=${c.id}" style="${cur && c.id === cur.id ? 'background:var(--soft);margin:0 -12px;padding:12px' : ''}">${avatar(c.title, null, 38)}<div class="grow" style="min-width:0"><b>${c.title}</b> <span class="muted xs">${c.kind === 'customer_agent' ? 'Customer' : 'Provider'}</span><div class="muted xs truncate">${c.last ? c.last.body : 'No messages yet'}</div></div></a>`)}</div>
      <div class="card"><div class="row between mb"><b>${cur.title}</b><span class="muted sm">${cur.subtitle}</span></div><div id="chat-box" style="max-height:52vh;overflow-y:auto"></div>${composer('Type a message…')}</div></div>` : emptyState({ ic: 'chat', title: 'No conversations', text: 'Start a conversation with a provider from the directory.' })}`;
}

// ---------------------------------------------------------------- complaints
async function complaints(ctx) {
  const lv = lead(ctx.user);
  const open = async (id) => {
    const t = await api('/complaints/' + id);
    modal({ title: `${t.reference} · ${t.topic}`, wide: true, footer: false, body: S(`<div class="row-gap" style="gap:8px">${chip(cap(t.kind.replace('_', ' ')), 'info').toString()} ${chip(cap(t.status), ['resolved', 'closed'].includes(t.status) ? 'success' : 'warn').toString()} ${t.priority === 'high' ? chip('High priority', 'danger').toString() : ''} ${t.overdue ? chip('SLA overdue', 'danger').toString() : ''}</div><p class="mt">${esc(t.description)}</p><p class="muted sm">Raised by ${esc(t.raised_by_name)} (${esc(t.raised_by_role)})${t.against_name ? ' against ' + esc(t.against_name) : ''}${t.request_reference ? ' · ' + esc(t.request_reference) : ''} · SLA ${esc(dt(t.sla_due_at))}</p>${t.resolution ? `<div class="note note-success">${esc(t.resolution)}</div>` : ''}
      <h3 class="mt mb">History</h3>${timeline(t.events.map((e) => ({ title: cap(e.event.replace('_', ' ')), time: dt(e.created_at), note: (e.actor ? e.actor + ': ' : '') + (e.note || '') }))).toString()}
      ${['resolved', 'closed'].includes(t.status) ? '' : `<form id="f-t" class="mt" novalidate><div class="grid g2"><div class="field"><label for="ts">Update status</label><select id="ts" name="status"><option value="">Keep ${esc(cap(t.status))}</option><option value="investigating">Investigating</option><option value="escalated">Escalate to team lead</option><option value="resolved">Resolve</option></select></div>${t.kind === 'dispute' ? '<div class="field"><label for="to">If resolving a dispute</label><select id="to" name="outcome"><option value="completed">Service stands (complete)</option><option value="cancelled">Cancel the booking</option></select></div>' : ''}</div><div class="field"><label for="tn">Note / resolution</label><textarea id="tn" name="note" rows="3"></textarea><div class="field-error" data-error-for="resolution"></div></div><label class="check"><input type="checkbox" name="internal"> <span>Internal note (not visible to the customer)</span></label><div class="form-error" role="alert" hidden></div><div class="row-gap mt"><button class="btn btn-primary" type="submit">Save update</button></div></form>`}`),
      onMount: (m, close) => { const f = m.querySelector('#f-t'); f && f.addEventListener('submit', async (ev) => { ev.preventDefault(); const d = Object.fromEntries(new FormData(f)); const b = f.querySelector('[type=submit]'); b.disabled = true;
        try { if (d.status) await api('/complaints/' + t.id, { method: 'PATCH', body: { status: d.status, resolution: d.status === 'resolved' ? d.note : undefined, outcome: d.outcome } }); else if (d.note) await api(`/complaints/${t.id}/notes`, { method: 'POST', body: { note: d.note, internal: !!d.internal } });
          toast('Ticket updated.'); close(); ctx.reload(); } catch (e) { const bn = f.querySelector('.form-error'); bn.textContent = e.message; bn.hidden = false; if (e.fields && e.fields.resolution) m.querySelector('[data-error-for=resolution]').textContent = e.fields.resolution; b.disabled = false; } }); } });
  };
  ctx.after(() => mountTable(ctx.view.querySelector('#tbl'), {
    load: (p) => api('/complaints' + qs(p)), search: 'Search ticket, topic or text', pageSize: 10,
    filters: [{ key: 'status', label: 'All statuses', options: [['open', 'Open'], ['investigating', 'Investigating'], ['escalated', 'Escalated'], ['resolved', 'Resolved']] }, { key: 'kind', label: 'All types', options: [['complaint', 'Complaints'], ['dispute', 'Disputes'], ['partner_issue', 'Partner issues']] }],
    columns: [{ label: 'Ticket', render: (t) => html`<b>${t.topic}</b> ${t.priority === 'high' ? chip('High', 'danger') : ''}<span class="sub">${t.reference} · ${t.raised_by_name}</span>` }, { label: 'Type', render: (t) => cap(t.kind.replace('_', ' ')) }, { label: 'Request', render: (t) => t.request_reference || '—' }, { label: 'Owner', render: (t) => t.owner_name || 'Unassigned' },
      { label: 'SLA', render: (t) => (['resolved', 'closed'].includes(t.status) ? '—' : t.overdue ? chip('Overdue', 'danger') : ago(t.sla_due_at)) }, { label: 'Status', render: (t) => chip(cap(t.status), ['resolved', 'closed'].includes(t.status) ? 'success' : t.status === 'escalated' ? 'danger' : 'warn') }, { label: '', cls: 'act', render: () => rowBtn('open', 'Open') }],
    actions: { open: (t) => open(t.id) }, empty: { ic: 'shield', title: 'No complaints', text: 'Issues raised by customers and partners appear here with SLAs.' },
  }));
  return html`${pageHeader('Complaints & escalation', 'Resolve issues with clear ownership and SLA.')}<div id="tbl"></div>`;
}

// ---------------------------------------------------------------- Quick Jobs operations
async function jobs(ctx) {
  const tab = ctx.query.tab || 'verify';
  const VS = { pending_verification: ['To verify', 'warn'], published: ['Live', 'success'], paused: ['Paused', 'neutral'], closed: ['Closed', 'neutral'], rejected: ['Rejected', 'danger'], filled: ['Filled', 'success'] };
  let t;
  const verifyV = async (v, approve) => {
    if (approve) { try { await api(`/vacancies/${v.id}/verify`, { method: 'POST', body: { action: 'approve' } }); toast('Vacancy published.'); t.reload(); } catch (e) { toast(e.message, 'error'); } return; }
    modal({ title: 'Reject vacancy', danger: true, submitLabel: 'Reject', body: field({ name: 'reason', label: 'What should the employer fix?', type: 'textarea', required: true, value: '' }).toString(), onSubmit: async (d) => { await api(`/vacancies/${v.id}/verify`, { method: 'POST', body: { action: 'reject', reason: d.reason } }); toast('Vacancy rejected.'); t.reload(); } });
  };
  ctx.after(() => {
    const el = ctx.view.querySelector('#tbl');
    if (tab === 'employers') t = mountTable(el, { load: (p) => api('/employers' + qs(p)), search: false, filters: [{ key: 'status', label: 'All', options: [['pending', 'Pending'], ['verified', 'Verified'], ['rejected', 'Rejected'], ['blocked', 'Blocked']] }],
      columns: [{ label: 'Employer', render: (e) => html`<b>${e.company_name}</b><span class="sub">${e.industry} · ${e.locality}</span>` }, { label: 'Contact', render: (e) => html`${e.contact_name}<span class="sub">${phone(e.phone)}</span>` }, { label: 'Vacancies', cls: 'num', render: (e) => e.vacancies }, { label: 'Status', render: (e) => chip(cap(e.verification_status), { verified: 'success', pending: 'warn', rejected: 'danger', blocked: 'danger' }[e.verification_status]) },
        { label: '', cls: 'act', render: (e) => html`${e.verification_status !== 'verified' ? rowBtn('verify', 'Verify', 'btn-primary btn-sm') : ''}${e.verification_status !== 'blocked' ? rowBtn('block', 'Block') : ''}` }],
      actions: { verify: async (e) => { await api(`/employers/${e.id}/verify`, { method: 'POST', body: { action: 'verify' } }); toast('Employer verified.'); t.reload(); }, block: async (e) => { const r = await confirmDialog({ title: 'Block this employer?', message: 'Their live vacancies are closed immediately.', confirmLabel: 'Block', danger: true }); if (r) { await api(`/employers/${e.id}/verify`, { method: 'POST', body: { action: 'block' } }); t.reload(); } } }, empty: { ic: 'users', title: 'No employers', text: '' } });
    else if (tab === 'reports') t = mountTable(el, { load: (p) => api('/job-reports' + qs(p)), search: false, filters: [{ key: 'status', label: 'All', options: [['open', 'Open'], ['actioned', 'Actioned'], ['dismissed', 'Dismissed']] }],
      columns: [{ label: 'Vacancy', render: (r) => html`<b>${r.title}</b><span class="sub">${r.reference} · ${r.company_name}</span>` }, { label: 'Report', render: (r) => r.reason }, { label: 'By', render: (r) => r.reporter }, { label: 'Status', render: (r) => chip(cap(r.status), r.status === 'open' ? 'warn' : 'neutral') }, { label: '', cls: 'act', render: (r) => (r.status === 'open' ? html`${rowBtn('unpub', 'Unpublish', 'btn-danger-o btn-sm')}${rowBtn('dismiss', 'Dismiss')}` : '') }],
      actions: { unpub: async (r) => { await api(`/job-reports/${r.id}/resolve`, { method: 'POST', body: { action: 'unpublish' } }); toast('Vacancy unpublished.'); t.reload(); }, dismiss: async (r) => { await api(`/job-reports/${r.id}/resolve`, { method: 'POST', body: { action: 'dismiss' } }); t.reload(); } }, empty: { ic: 'shield', title: 'No reports', text: 'Candidate reports of misleading vacancies appear here.' } });
    else t = mountTable(el, { load: (p) => api('/vacancies' + qs({ ...p, status: tab === 'verify' ? 'pending_verification' : p.status })), search: 'Search vacancies', filters: tab === 'all' ? [{ key: 'status', label: 'All statuses', options: Object.entries(VS).map(([k, v]) => [k, v[0]]) }] : [],
      columns: [{ label: 'Vacancy', render: (v) => html`<b>${v.title}</b><span class="sub">${v.reference} · ${v.company_name} ${v.employer_verification === 'verified' ? '✓' : '(unverified employer)'}</span>` }, { label: 'Salary', render: (v) => `${inr(v.salary_min)}–${inr(v.salary_max)}/${v.pay_frequency}` }, { label: 'Where', render: (v) => v.locality }, { label: 'Applicants', cls: 'num', render: (v) => v.applicants }, { label: 'Status', render: (v) => chip(...VS[v.status]) },
        { label: '', cls: 'act', render: (v) => (v.status === 'pending_verification' ? html`${rowBtn('approve', 'Approve', 'btn-primary btn-sm')}${rowBtn('reject', 'Reject')}` : '') }],
      actions: { approve: (v) => verifyV(v, true), reject: (v) => verifyV(v, false) }, empty: { ic: 'briefcase', title: tab === 'verify' ? 'Nothing to verify' : 'No vacancies', text: 'New vacancies need verification before candidates can see them.' } });
  });
  return html`${pageHeader('Quick Jobs operations', 'Verify vacancies and coordinate the candidate flow. BUZZER never allows recruitment fees.')}${tabs([['verify', 'To verify'], ['all', 'All vacancies'], ['employers', 'Employers'], ['reports', 'Reports']], tab, ctx.portal === 'admin' ? '#/x/jobs' : '#/a/jobs')}<div id="tbl" class="mt"></div>`;
}

async function events(ctx) {
  const d = await api('/agent/events');
  return html`${pageHeader('Events & wedding operations', 'Coordinate vendors and event milestones across weddings, catering and photography.')}
    ${d.items.length ? html`<div class="auto-grid">${d.items.map((e) => html`<a class="card card-link" href="#/a/request/${e.id}"><div class="row between"><b>${e.title}</b>${statusChip(e.status, e.status_label)}</div><div class="muted sm">${e.reference} · ${e.customer_name}</div>${kv([['Event', `${e.event_type || ''} · ${e.event_date || ''}`], ['Guests', e.guest_count], ['Budget', e.budget_min || e.budget_max ? `${inr(e.budget_min)}–${inr(e.budget_max)}` : '—'], ['Services', e.services]])}<div class="mt"><div class="row between sm muted"><span>Milestones</span><span>${e.milestones_done}/${e.milestones_total}</span></div>${progress(e.milestones_total ? Math.round((e.milestones_done * 100) / e.milestones_total) : 0, 'Milestones')}</div></a>`)}</div>` : emptyState({ ic: 'gift', title: 'No event briefs assigned', text: 'Wedding, catering and photography briefs assigned to you appear here.' })}`;
}

// ---------------------------------------------------------------- performance
async function performance(ctx) {
  const aid = ctx.query.agent_id;
  const d = await api('/agent/performance' + qs({ agent_id: aid }));
  const m = d.me;
  return html`${pageHeader('Agent performance', `${m.name} — measure service quality, not just number of calls.`)}
    <div class="grid g4">${stat({ label: 'Active customers', value: m.customers, ic: 'users' })}${stat({ label: 'Open requests', value: `${m.open_requests}/${m.capacity}`, ic: 'inbox' })}${stat({ label: 'Avg first response', value: m.response_hours != null ? hoursText(m.response_hours) : '—', ic: 'clock' })}${stat({ label: 'Quote turnaround', value: m.quote_turnaround_hours != null ? hoursText(m.quote_turnaround_hours) : '—', ic: 'file' })}
      ${stat({ label: 'Completion rate', value: m.completion_rate != null ? m.completion_rate + '%' : '—', ic: 'check' })}${stat({ label: `Customer rating (${m.rating_count})`, value: m.rating ? m.rating + ' ★' : '—', ic: 'star' })}${stat({ label: 'Quote conversion', value: m.quote_conversion != null ? m.quote_conversion + '%' : '—', ic: 'trend' })}${stat({ label: 'Complaint rate', value: m.complaint_rate + '%', ic: 'alert', tone: m.complaint_rate > 5 ? 'warn' : '' })}</div>
    <div class="split mt"><div class="card"><h2 class="mb">Requests per week</h2>${barChart({ labels: d.weeks.map((w) => w.label), series: [{ name: 'Received', color: '#1B231E', values: d.weeks.map((w) => w.received) }, { name: 'Completed', color: '#BEEB5D', values: d.weeks.map((w) => w.completed) }] })}</div>
      <div class="card"><h2 class="mb">Open work by status</h2>${d.open_by_status.length ? hbars(d.open_by_status.map((s) => ({ label: s.label, value: s.n }))) : html`<p class="muted">No open work.</p>`}<hr class="divider"><div class="row between sm"><span class="muted">Workload</span><b>${m.open_requests} / ${m.capacity}</b></div><div class="gauge mt ${m.open_requests / m.capacity > 0.9 ? 'hot' : ''}"><i style="width:${Math.min(100, (m.open_requests * 100) / m.capacity)}%"></i></div></div></div>
    ${d.team ? section('Team workload distribution', html`<div class="table-wrap"><table class="table"><thead><tr><th>Agent</th><th class="num">Customers</th><th class="num">Open</th><th>Capacity</th><th class="num">Resp.</th><th class="num">Completion</th><th class="num">Rating</th><th class="num">Complaints</th></tr></thead><tbody>${d.team.map((a) => html`<tr><td data-label="Agent"><b>${a.name}</b> ${chip(cap(a.availability), a.availability === 'available' ? 'success' : 'warn')}</td><td class="num" data-label="Customers">${a.customers}</td><td class="num" data-label="Open">${a.open_requests}</td><td data-label="Capacity"><div class="gauge ${a.open_requests / a.capacity > 0.9 ? 'hot' : a.open_requests / a.capacity > 0.7 ? 'warm' : ''}"><i style="width:${Math.min(100, (a.open_requests * 100) / a.capacity)}%"></i></div></td><td class="num" data-label="Response">${a.response_hours != null ? hoursText(a.response_hours) : '—'}</td><td class="num" data-label="Completion">${a.completion_rate != null ? a.completion_rate + '%' : '—'}</td><td class="num" data-label="Rating">${a.rating || '—'}</td><td class="num" data-label="Complaints">${a.complaint_rate}%</td></tr>`)}</tbody></table></div>`) : ''}`;
}

export { jobs, complaints, bookingDetail };
export const routes = [
  ['/a/home', home], ['/a/customers', customers], ['/a/customer/:id', customerProfile], ['/a/requests', requests], ['/a/request/:id', requestDetail], ['/a/providers', providers], ['/a/outreach', outreach],
  ['/a/quotes', quotes], ['/a/compare/:id', compare], ['/a/approvals', approvals], ['/a/bookings', bookings], ['/a/booking/:id', bookingDetail], ['/a/tracking', tracking], ['/a/tasks', tasks],
  ['/a/messages', messages], ['/a/complaints', complaints], ['/a/jobs', jobs], ['/a/events', events], ['/a/performance', performance],
];
